from datetime import datetime, timedelta


class Scheduler:
    def __init__(self) -> None:
        self._appointments = {}  # id -> dict
        self._next_id = 1

    def book(self, patient: str, doctor: str, start: datetime, end: datetime,
             now: datetime) -> int:
        if start < now:
            raise ValueError("Cannot book an appointment in the past")
        if end <= start:
            raise ValueError("End must be after start")

        # At most one upcoming appointment per patient
        for appt in self._appointments.values():
            if (appt["patient"] == patient
                    and not appt["cancelled_freely"]
                    and appt["end"] > now):
                raise ValueError(
                    "Patient already has an upcoming appointment")

        if not self.is_free(doctor, start, end):
            raise ValueError("Doctor is not free during that time")

        appt_id = self._next_id
        self._next_id += 1
        self._appointments[appt_id] = {
            "patient": patient,
            "doctor": doctor,
            "start": start,
            "end": end,
            # If True, the time slot is no longer blocked.
            "cancelled_freely": False,
        }
        return appt_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        appt = self._appointments.get(appointment_id)
        if appt is None:
            raise ValueError("Unknown appointment id")
        if appt["cancelled_freely"]:
            return  # already cancelled and freed
        if appt["start"] - now < timedelta(hours=24):
            # Too late: slot stays blocked, but we can't book again on it.
            # Mark it as a no-op cancellation that keeps the slot blocked.
            raise ValueError(
                "Cannot cancel less than 24 hours before start")
        appt["cancelled_freely"] = True

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        for appt in self._appointments.values():
            if appt["cancelled_freely"]:
                continue
            if appt["doctor"] != doctor:
                continue
            # Overlap iff start < appt.end and end > appt.start
            if start < appt["end"] and end > appt["start"]:
                return False
        return True
